-- Find the query_id and plan_id from Query Store
SELECT 
    q.query_id,
    p.plan_id,
    q.query_text,
    rs.avg_duration,
    rs.execution_type_desc
FROM sys.query_store_query_text AS qt
INNER JOIN sys.query_store_query AS q ON qt.query_text_id = q.query_text_id
INNER JOIN sys.query_store_plan AS p ON q.query_id = p.query_id
INNER JOIN sys.query_store_runtime_stats AS rs ON p.plan_id = rs.plan_id
WHERE q.query_id = 42;

-- Force the last known good plan
EXEC sp_query_store_force_plan
    @query_id = 42,
    @plan_id = 1;

-- Unforce the plan when the underlying issue is resolved
EXEC sp_query_store_unforce_plan
    @query_id = 42;
